// Builds the static Quran and prayer-time files in public/ from the source datasets.
// Usage: node tools/build-data.mjs <dir with ara/eng/div/info json> <path to salat.json>
// The generated files are committed, so this only needs re-running if a source changes.
import fs from 'node:fs';
import path from 'node:path';

const [src, salatPath] = process.argv.slice(2);
const out = path.resolve('public');
const load = (f) => JSON.parse(fs.readFileSync(path.join(src, f), 'utf8'));

const ar = load('ara-quranuthmanihaf.json').quran;
const en = load('eng-mohammedmarmadu.json').quran;
const dv = load('div.json').quran;
const info = load('info.json');

const clean = (s) => s.replace(/\s+/g, ' ').trim();
const index = [];
const pages = {}, firstPage = {};
let k = 0;
for (const ch of info.chapters) {
  const ayahs = [];
  const juz = [];
  for (const v of ch.verses) {
    const a = ar[k], e = en[k], d = dv[k];
    if (a.chapter !== ch.chapter || a.verse !== v.verse || e.verse !== v.verse || d.verse !== v.verse || d.chapter !== ch.chapter)
      throw new Error(`misaligned at ${ch.chapter}:${v.verse}`);
    // The source puts a space before the seat letter of an open tanween and adds stray direction marks; tidy both.
    const arText = clean(a.text.replace(/\u200f/g, '')).replace(/([\u08F0-\u08F2]) ([اى])(?![\u0621-\u064A\u0671])/g, '$1$2');
    ayahs.push([arText, clean(e.text), clean(d.text)]);
    juz.push(v.juz);
    (pages[v.page] ||= { p: v.page, juz: v.juz, ayahs: [] }).ayahs.push([ch.chapter, v.verse, arText]);
    if (v.verse === 1) firstPage[ch.chapter] = v.page;
    k++;
  }
  const meta = {
    n: ch.chapter,
    name: ch.name,
    en: ch.englishname,
    ar: ch.arabicname.replace(/^سُوْرَةُ\s*/, ''),
    rev: ch.revelation === 'Mecca' ? 'M' : 'D',
    count: ayahs.length,
    juz: juz[0],
    page: firstPage[ch.chapter],
  };
  index.push(meta);
  fs.writeFileSync(path.join(out, 'quran', `${ch.chapter}.json`), JSON.stringify({ ...meta, juzOf: juz, sajda: ch.verses.filter((v) => v.sajda).map((v) => v.verse), ayahs }));
}
if (k !== 6236) throw new Error('expected 6236 ayahs, got ' + k);
// Mushaf view: one small file per page of the standard 604-page Madinah layout.
fs.mkdirSync(path.join(out, 'quran', 'page'), { recursive: true });
for (const pg of Object.values(pages)) fs.writeFileSync(path.join(out, 'quran', 'page', `${pg.p}.json`), JSON.stringify(pg));
if (Object.keys(pages).length !== 604) throw new Error('expected 604 pages');
const juzStarts = info.juzs.references.map((j) => [j.juz, j.start.chapter, j.start.verse]);
fs.writeFileSync(path.join(out, 'quran', 'index.json'), JSON.stringify({ surahs: index, juz: juzStarts }));

// Prayer times: one compact file for the app, plus one tiny file per day for the cron job.
const salat = JSON.parse(fs.readFileSync(salatPath, 'utf8'));
const P = ['fajr', 'sunrise', 'dhuhr', 'asr', 'maghrib', 'isha'];
const groups = {};
for (const [g, days] of Object.entries(salat.atolls)) {
  const rows = new Array(366);
  for (const d of days) rows[d.day] = P.map((p) => d[p]);
  if (rows.some((r) => !r)) throw new Error('missing day in group ' + g);
  groups[g] = rows;
}
const islands = salat.islands
  .map((i) => ({ id: i.islandId, a: i.atoll.replace('.', ''), n: i.island, g: i.atollId, o: i.offset }))
  .sort((x, y) => x.id - y.id);
fs.writeFileSync(path.join(out, 'data', 'prayer.json'), JSON.stringify({ islands, groups }));
fs.mkdirSync(path.join(out, 'data', 'day'), { recursive: true });
for (let d = 0; d < 366; d++) {
  const day = {};
  for (const g of Object.keys(groups)) day[g] = groups[g][d];
  fs.writeFileSync(path.join(out, 'data', 'day', `${d}.json`), JSON.stringify(day));
}
fs.writeFileSync(path.resolve('src', 'islands.js'), `// Generated by tools/build-data.mjs. [islandId, groupId, offsetMinutes]\nexport const ISLANDS = ${JSON.stringify(islands.map((i) => [i.id, i.g, i.o]))};\n`);
console.log('surahs', index.length, 'ayahs', k, 'islands', islands.length, 'groups', Object.keys(groups).length);
